# ==============================================================================# 037_TASK_QUEUE_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS task_queue(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    task_name TEXT,    priority TEXT,    origin TEXT,    status TEXT,    started_at TEXT,    finished_at TEXT)""")conn.commit()TASKS = [("Verify Health","HIGH","HEALTH CHECK"),("Collect Metrics","NORMAL","METRICS"),("Read Events","NORMAL","EVENT ENGINE"),("Audit System","LOW","AUDIT"),("Send Notifications","NORMAL","NOTIFICATION"),("Synchronize API","HIGH","API CORE")]for task,priority,origin in TASKS:    cur.execute(        """        SELECT id        FROM task_queue        WHERE task_name=?        AND status='PENDING'        """,        (task,)    )    if cur.fetchone() is None:        cur.execute("""        INSERT INTO task_queue(            created_at,            task_name,            priority,            origin,            status,            started_at,            finished_at        )        VALUES(?,?,?,?,?,?,?)        """,(            datetime.now().isoformat(),            task,            priority,            origin,            "PENDING",            None,            None        ))conn.commit()cur.execute("""SELECTid,task_name,priority,origin,statusFROM task_queueORDER BYCASE priorityWHEN 'HIGH' THEN 1WHEN 'NORMAL' THEN 2WHEN 'LOW' THEN 3END,id""")print("="*80)print("TASK QUEUE ENGINE")print("="*80)rows = cur.fetchall()for row in rows:    print(        f"{row['id']:03d} "        f"{row['priority']:<8}"        f"{row['task_name']:<24}"        f"{row['origin']:<18}"        f"{row['status']}"    )print("="*80)print("TOTAL TASKS:", len(rows))print("="*80)conn.close()

